public class Main {
    public static void main(String[] args) {
        Box<String> name = new Box<>("Asha");
        Box<Integer> age = new Box<>(30);
        System.out.println(name.get().toUpperCase());
        System.out.println(age.get() + 1);
    }
}

class Box<T> {
    private final T value;

    Box(T value) {
        this.value = value;
    }

    T get() {
        return value;
    }
}
